/** Real typed-target immutable object intent, one physical attempt, and artifact registration. */
public final class TaskStrictFieldTypedTargetLedger {
    private final JdbcTemplate db;private final StrictComparisonCodec codec;private final ArtifactRegistryMapper registry;private final DependencyManifestSchema dependencies;
    private final DependencyLineage lineage;private final TaskFieldTargetPolicy bounds;private final IdentityDirectoryPolicy identity;private final VersionResourceMapper owners;
    TaskStrictFieldTypedTargetLedger(DataSource data,StrictComparisonCodec codec,ArtifactRegistryMapper registry,DependencyManifestSchema dependencies,DependencyLineage lineage,TaskFieldTargetPolicy bounds,IdentityDirectoryPolicy identity,VersionResourceMapper owners){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.codec=codec;this.registry=registry;this.dependencies=dependencies;this.lineage=lineage;this.bounds=bounds;this.identity=identity;this.owners=owners;}
    String manifest()throws Exception{return codec.hash(Map.of("typed_protocol",StrictComparisonCodec.implementation(TaskStrictFieldTypedProtocol.class,"STRICT_FIELD_TYPED_PROTOCOL_V1"),"target_schema",new StrictFieldComparisonSchema().schemaSha256()));}
    String targetDigest(String version)throws Exception{return "2.0.0".equals(version)?SchemaCatalogue.fromClasspath().schemaDigest("strict-field-typed-v2"):manifest();}
    Attempt prepare(TaskStrictFieldTypedTargetService.Verified proof,String key,RuntimeObjectTransport.StorageBinding storage)throws Exception{
        proof.requireApproved();var a=proof.admission();TaskFieldMappingService.key(key);String tenant=a.context().tenant_id();var existing=db.queryForList("SELECT * FROM task_strict_field_typed_intent WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2 FOR UPDATE",tenant,a.actorId(),key);
        if(!existing.isEmpty()){var row=one(existing);verifyIntent(proof,row,storage);return new Attempt(row,true);}
        bounds.requireConfigured();var closure=closure(proof);String write=id(),artifact=id();String payload=codec.canonical(proof.manifest()),hash=codec.hash(proof.manifest());if(payload.getBytes(StandardCharsets.UTF_8).length>bounds.maximumTargetBytes())limit();
        String objectKey="tenants/"+tenant+"/tasks/"+proof.request().scope().taskId()+"/strict-field-typed/"+write+"/"+artifact+".json";
        var intent=codec.tree(Map.of("target_revision",proof.revisionId(),"target_digest",proof.digest(),"decision",proof.decision(),"artifact_id",artifact,"write_id",write,"object_key",objectKey,"payload_sha256",hash,"storage",storage,"roots",closure.roots,"members",closure.members));
        String audit=id(),event=id();var now=now();var receipt=codec.tree(Map.of("kind","STRICT_FIELD_TYPED_INTENT","intent",intent,"audit_id",audit,"event_id",event,"created_by",a.actorId()));
        journal(a,proof.project(),write,"task.strict_field.typed.intent",receipt,audit,event,now);
        changed(db.update("INSERT INTO task_strict_field_typed_intent(tenant_id,project_id,task_id,write_id,artifact_id,target_revision,target_digest,created_by,idempotency_key,object_key,payload_sha256,canonical_payload,intent_json,intent_sha256,receipt_json,receipt_sha256,audit_id,event_id,created_at,classification,schema_version,schema_manifest_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?)",tenant,proof.project(),proof.request().scope().taskId(),write,artifact,proof.revisionId(),proof.digest(),a.actorId(),key,objectKey,hash,payload,codec.canonical(intent),codec.hash(intent),codec.canonical(receipt),codec.hash(receipt),audit,event,now,identity.classification(),manifest()));
        var row=one(db.queryForList("SELECT * FROM task_strict_field_typed_intent WHERE tenant_id=? AND write_id=? FOR UPDATE",tenant,write));verifyIntent(proof,row,storage);return new Attempt(row,false);
    }
    void require(TaskStrictFieldTypedTargetService.Verified proof,Attempt attempt,RuntimeObjectTransport.StorageBinding storage)throws Exception{if(attempt.owner!=this)deny();var row=one(db.queryForList("SELECT * FROM task_strict_field_typed_intent WHERE tenant_id=? AND write_id=? FOR UPDATE",attempt.tenantId(),attempt.writeId()));if(!row.equals(attempt.row))bad();verifyIntent(proof,row,storage);}
    private void verifyIntent(TaskStrictFieldTypedTargetService.Verified proof,Map<String,Object> row,RuntimeObjectTransport.StorageBinding storage)throws Exception{
        proof.requireApproved();var a=proof.admission();var intent=codec.read(str(row,"intent_json"));var receipt=codec.read(str(row,"receipt_json"));
        if(!a.context().tenant_id().equals(str(row,"tenant_id"))||!a.actorId().equals(str(row,"created_by"))||!proof.project().equals(str(row,"project_id"))||!proof.request().scope().taskId().equals(str(row,"task_id"))||!proof.revisionId().equals(str(row,"target_revision"))||!proof.digest().equals(str(row,"target_digest"))||!codec.hash(intent).equals(str(row,"intent_sha256"))||!codec.hash(receipt).equals(str(row,"receipt_sha256"))||!intent.equals(receipt.required("intent"))||!manifest().equals(str(row,"schema_manifest_sha256"))||!proof.manifest().equals(codec.read(str(row,"canonical_payload")))||!codec.hash(proof.manifest()).equals(str(row,"payload_sha256"))||!codec.tree(storage).equals(intent.required("storage"))||!codec.tree(proof.decision()).equals(intent.required("decision")))bad();
        for(String key:List.of("write_id","artifact_id","object_key","payload_sha256","target_revision","target_digest"))if(!str(row,key).equals(intent.required(key).asText()))bad();var closure=closure(proof);if(!codec.tree(closure.members).equals(intent.required("members"))||!codec.tree(closure.roots).equals(intent.required("roots")))bad();verifyJournal(a,proof.project(),str(row,"write_id"),"task.strict_field.typed.intent",receipt,str(row,"audit_id"),str(row,"event_id"),str(row,"created_by"));
    }
    JsonNode register(TaskStrictFieldTypedTargetService.Verified proof,Attempt attempt,RuntimeObjectTransport.VerifiedTransfer transfer,RuntimeObjectTransport.StorageBinding storage)throws Exception{
        require(proof,attempt,storage);if(transfer.originalAttempt()!=attempt)deny();var object=transfer.reference();if(!attempt.expectedObjectKey().equals(object.objectKey())||!attempt.writeIntent().sha256().equals(object.sha256())||!attempt.writeIntent().sizeBytes().equals(object.sizeBytes())||!"application/json".equals(object.mediaType()))bad();
        var old=db.queryForList("SELECT artifact_id FROM task_strict_field_typed_registration WHERE tenant_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",attempt.tenantId(),attempt.artifactId());if(!old.isEmpty()){var registered=registered(proof,attempt.artifactId());if(!object.equals(registered.reference()))bad();return registered.receipt();}
        var a=proof.admission();String tenant=attempt.tenantId(),project=proof.project(),artifact=attempt.artifactId(),set=id();var now=now();var closure=closure(proof);var dependency=new ArtifactRegistryProtocol.DependencyManifest("1.0.0",tenant,project,set,closure.members);String dependencyHash=codec.hash(dependency);
        version(tenant,project,set,"DEPENDENCY_ACCESS_SET",dependencyHash);var access=metadata(a,now,false);access.putAll(Map.of("project_id",project,"access_set_id",set,"manifest_sha256",dependencyHash,"content_sha256",dependencyHash));insert("dependency_access_set",access);
        var dm=metadata(a,now,true);dm.putAll(Map.of("project_id",project,"access_set_id",set,"schema_manifest_sha256",dependencies.manifestSha256(),"manifest_json",codec.canonical(dependency),"manifest_sha256",dependencyHash,"content_sha256",dependencyHash,"member_count",closure.members.size()));insert("dependency_access_manifest",dm);
        for(var member:closure.members){var m=metadata(a,now,false);m.putAll(Map.of("access_set_id",set,"upstream_version_id",member.upstreamVersionId(),"rights_revision",member.rightsRevision()));insert("dependency_access_member",m);}
        version(tenant,project,artifact,"ARTIFACT",object.sha256());var ar=metadata(a,now,true);ar.putAll(Map.of("project_id",project,"artifact_id",artifact,"artifact_kind","STRICT_FIELD_TARGET","object_ref",StoredObjectReferences.encode(object),"object_key",object.objectKey(),"object_version",object.objectVersion(),"sha256",object.sha256(),"size_bytes",object.sizeBytes(),"media_type",object.mediaType()));ar.put("dependency_access_set_id",set);ar.put("content_sha256",object.sha256());ar.put("run_id",null);ar.put("document_revision",null);insert("artifact",ar);
        var binding=metadata(a,now,false);binding.putAll(Map.of("project_id",project,"artifact_id",artifact,"resource_kind","TASK","resource_id",proof.request().scope().taskId(),"schema_ref",TaskStrictFieldTypedProtocol.targetRef(proof.request().schemaVersion()),"schema_document_sha256",targetDigest(proof.request().schemaVersion()),"dependency_access_set_id",set,"dependency_manifest_sha256",dependencyHash));insert("artifact_content_binding",binding);
        for(String root:closure.roots)insert("lineage_edge",Map.of("tenant_id",tenant,"consumer_version_id",artifact,"upstream_version_id",root,"relation_kind","STRICT_FIELD_TYPED_SOURCE","actor_id",a.actorId(),"created_at",now));lineage.require(artifact,closure.members,bounds.lineageLimits());
        String audit=id(),event=id();var receipt=codec.tree(Map.of("schema_version","1.0.0","kind","STRICT_FIELD_TYPED_REGISTRATION","artifact_id",artifact,"target_revision",proof.revisionId(),"target_digest",proof.digest(),"write_id",attempt.writeId(),"object_ref",object,"decision",proof.decision(),"audit_id",audit,"event_id",event));journal(a,project,artifact,"task.strict_field.typed.registered",receipt,audit,event,now);
        changed(db.update("INSERT INTO task_strict_field_typed_registration(tenant_id,project_id,task_id,artifact_id,write_id,target_revision,target_digest,object_sha256,receipt_json,receipt_sha256,audit_id,event_id,created_by,created_at,classification,schema_version,schema_manifest_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?)",tenant,project,proof.request().scope().taskId(),artifact,attempt.writeId(),proof.revisionId(),proof.digest(),object.sha256(),codec.canonical(receipt),codec.hash(receipt),audit,event,a.actorId(),now,identity.classification(),manifest()));return registered(proof,artifact).receipt();
    }
    Registered registered(TaskStrictFieldTypedTargetService.Verified proof,String artifact)throws Exception{
        proof.requireApproved();var a=proof.admission();var row=one(db.queryForList("SELECT * FROM task_strict_field_typed_registration WHERE tenant_id=? AND project_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),proof.project(),artifact));var receipt=codec.read(str(row,"receipt_json"));
        if(!proof.revisionId().equals(str(row,"target_revision"))||!proof.digest().equals(str(row,"target_digest"))||!codec.hash(receipt).equals(str(row,"receipt_sha256"))||!codec.tree(proof.decision()).equals(receipt.required("decision"))||!proof.request().scope().taskId().equals(str(row,"task_id")))bad();
        var intentRow=one(db.queryForList("SELECT * FROM task_strict_field_typed_intent WHERE tenant_id=? AND write_id=? FOR UPDATE",a.context().tenant_id(),str(row,"write_id")));var intent=codec.read(str(intentRow,"intent_json"));var originalReceipt=codec.read(str(intentRow,"receipt_json"));
        if(!codec.hash(intent).equals(str(intentRow,"intent_sha256"))||!intent.equals(originalReceipt.required("intent"))||!codec.hash(originalReceipt).equals(str(intentRow,"receipt_sha256"))||!proof.manifest().equals(codec.read(str(intentRow,"canonical_payload")))||!codec.hash(proof.manifest()).equals(str(intentRow,"payload_sha256"))||!codec.tree(proof.decision()).equals(intent.required("decision"))||!manifest().equals(str(intentRow,"schema_manifest_sha256")))bad();
        for(String key:List.of("tenant_id","project_id","task_id","artifact_id","write_id","target_revision","target_digest","created_by","classification"))if(!str(row,key).equals(str(intentRow,key)))bad();for(String key:List.of("artifact_id","write_id","target_revision","target_digest","object_key","payload_sha256"))if(!str(intentRow,key).equals(intent.required(key).asText()))bad();
        if(!codec.tree(closure(proof).members).equals(intent.required("members"))||!codec.tree(closure(proof).roots).equals(intent.required("roots")))bad();verifyJournal(a,proof.project(),str(intentRow,"write_id"),"task.strict_field.typed.intent",originalReceipt,str(intentRow,"audit_id"),str(intentRow,"event_id"),str(intentRow,"created_by"));
        var ar=one(registry.artifact(artifact));var binding=one(registry.binding(artifact));var object=ar.reference();StoredObjectReferences.decode(ar.storedObject(),object);
        if(!object.objectKey().equals(str(intentRow,"object_key"))||!a.context().tenant_id().equals(ar.tenantId())||!proof.project().equals(ar.projectId())||!"STRICT_FIELD_TARGET".equals(ar.artifactKind())||!codec.hash(proof.manifest()).equals(object.sha256())||!codec.tree(object).equals(receipt.required("object_ref"))||!object.sha256().equals(ar.contentSha256())||!object.sha256().equals(str(row,"object_sha256"))||!manifest().equals(ar.schemaManifest())||!"TASK".equals(binding.resourceKind())||!proof.request().scope().taskId().equals(binding.resourceId())||!TaskStrictFieldTypedProtocol.targetRef(proof.request().schemaVersion()).equals(binding.schemaRef())||!targetDigest(proof.request().schemaVersion()).equals(binding.schemaDocumentSha256())||!ar.accessSetId().equals(binding.accessSetId()))bad();
        var version=one(registry.version(artifact));if(!"ARTIFACT".equals(version.entityKind())||!proof.project().equals(version.projectId())||!object.sha256().equals(version.contentSha256()))bad();
        var dm=one(registry.manifest(ar.accessSetId()));var members=registry.members(ar.accessSetId());dependencies.verify(dm,members);if(!dm.manifestSha256().equals(binding.dependencyManifestSha256())||!members.equals(closure(proof).members))bad();lineage.require(artifact,members,bounds.lineageLimits());
        verifyJournal(a,proof.project(),artifact,"task.strict_field.typed.registered",receipt,str(row,"audit_id"),str(row,"event_id"),str(row,"created_by"));return new Registered(proof,artifact,object,receipt,str(row,"receipt_sha256"));
    }
    public final class Registered{
        private final TaskStrictFieldTypedTargetService.Verified proof;private final String artifact;private final ObjectRef reference;private final JsonNode receipt;private final String receiptHash;
        private Registered(TaskStrictFieldTypedTargetService.Verified proof,String artifact,ObjectRef reference,JsonNode receipt,String receiptHash){this.proof=proof;this.artifact=artifact;this.reference=reference;this.receipt=receipt;this.receiptHash=receiptHash;}
        public void requireUnchanged()throws Exception{var current=registered(proof,artifact);if(!receipt.equals(current.receipt)||!reference.equals(current.reference))bad();}
        public String artifactId(){return artifact;}public ObjectRef reference(){return reference;}public JsonNode receipt(){return receipt.deepCopy();}public String receiptSha256(){return receiptHash;}TaskStrictFieldTypedTargetService.Verified target(){return proof;}
    }
    public final class Attempt implements RuntimeObjectAttempt {
        private final TaskStrictFieldTypedTargetLedger owner=TaskStrictFieldTypedTargetLedger.this;private final Map<String,Object> row;private final boolean prior;private final AtomicBoolean claimed=new AtomicBoolean();private final Thread thread=Thread.currentThread();private volatile boolean committed;
        private Attempt(Map<String,Object> row,boolean prior){this.row=Map.copyOf(row);this.prior=prior;if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isSynchronizationActive())deny();TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){committed=true;}public void afterCompletion(int status){if(status!=STATUS_COMMITTED)committed=false;}});}
        public String tenantId(){return str(row,"tenant_id");}public String actorId(){return str(row,"created_by");}String writeId(){return str(row,"write_id");}String artifactId(){return str(row,"artifact_id");}
        public String expectedObjectKey(){return str(row,"object_key");}public byte[] bytes(){return str(row,"canonical_payload").getBytes(StandardCharsets.UTF_8);}public boolean priorAttempt(){return prior;}
        public S3ObjectWriter.WriteIntent writeIntent(){return new S3ObjectWriter.WriteIntent(writeId(),expectedObjectKey(),str(row,"payload_sha256"),Integer.toString(bytes().length),"application/json");}
        public TransferMode claimTransferMode(){if(!committed||thread!=Thread.currentThread()||TransactionSynchronizationManager.isActualTransactionActive())deny();return prior||!claimed.compareAndSet(false,true)?TransferMode.RECOVER_ONLY:TransferMode.INITIAL_WRITE;}
    }
    private record Closure(List<String> roots,List<ArtifactRegistryProtocol.MemberRow> members){}
    private Closure closure(TaskStrictFieldTypedTargetService.Verified proof)throws Exception{
        var roots=new TreeSet<String>();var rights=new HashMap<String,String>();var contexts=new ArrayList<PermissionProtocol.Basis>();for(var entry:proof.request().entries()){contexts.add(entry.candidateContext());contexts.add(entry.observedContext());}for(var requirement:proof.request().requirements())for(var indicator:requirement.indicators())for(var method:indicator.methods())contexts.add(method.sourceContext());for(var pin:contexts){
            var context=one(db.queryForList("SELECT request_json FROM task_strict_field_context_revision WHERE tenant_id=? AND project_id=? AND revision_id=? AND content_sha256=? LIMIT 2 FOR UPDATE",proof.admission().context().tenant_id(),proof.project(),pin.version_id(),pin.content_sha256()));var r=codec.bind(codec.read(str(context,"request_json")),TaskStrictFieldTypedProtocol.ContextAuthor.class);roots.add(r.evidence().sourceVersion());roots.add(r.evidence().parseVersion());var previous=rights.putIfAbsent(r.evidence().sourceVersion(),r.rightsRevision());if(previous!=null&&!previous.equals(r.rightsRevision()))bad();}
        for(var entry:proof.request().entries())if(entry.candidateExact()!=null){roots.add(entry.candidateExact().fieldRevision());roots.add(entry.observedExact().fieldRevision());}
        var versions=new TreeMap<String,ArtifactRegistryProtocol.VersionRow>();var edges=new HashSet<SourceReadProtocol.ParentRow>();for(String root:roots){var graph=lineage.inspect(root,bounds.lineageLimits());for(var e:graph.versions().entrySet()){var old=versions.putIfAbsent(e.getKey(),e.getValue());if(old!=null&&!old.equals(e.getValue()))bad();}edges.addAll(graph.graph().edgeSet());if(versions.size()>bounds.lineageLimits().maximumVersions()||edges.size()>bounds.lineageLimits().maximumRelations())limit();}
        var members=new ArrayList<ArtifactRegistryProtocol.MemberRow>();var mapped=owners.ownersAcrossDomains(List.copyOf(versions.keySet()),Arrays.stream(VersionResourceProtocol.Domain.values()).map(Enum::name).toList());for(var version:versions.values()){var owner=one(mapped.stream().filter(r->r.owner().versionId().equals(version.id())).toList()).owner();String right=rights.get(owner.sourceVersion());if(!proof.admission().context().tenant_id().equals(owner.tenantId())||!"SOURCE".equals(owner.resourceKind())||right==null||owner.conversationId()!=null||!TaskRunReplayContentAuthority.reachable(version.id(),owner.sourceVersion(),edges))bad();members.add(new ArtifactRegistryProtocol.MemberRow(version.id(),right));}return new Closure(List.copyOf(roots),List.copyOf(members));
    }
    private void journal(EnterpriseAccess.Admission a,String project,String id,String action,JsonNode receipt,String audit,String event,LocalDateTime now)throws Exception{changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",a.context().tenant_id(),project,audit,a.actorId(),action,codec.canonical(receipt),id,id,manifest(),a.actorId(),now,identity.classification()));changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,?,?,?)",a.context().tenant_id(),event,id,action,codec.canonical(receipt),now));}
    private void verifyJournal(EnterpriseAccess.Admission a,String project,String id,String action,JsonNode receipt,String audit,String event,String actor)throws Exception{var ar=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? FOR UPDATE",a.context().tenant_id(),audit));var ev=one(db.queryForList("SELECT * FROM outbox_event WHERE tenant_id=? AND event_id=? FOR UPDATE",a.context().tenant_id(),event));var table=action.endsWith(".intent")?"task_strict_field_typed_intent":"task_strict_field_typed_registration";var key=action.endsWith(".intent")?"write_id":"artifact_id";var original=one(db.queryForList("SELECT * FROM "+table+" WHERE tenant_id=? AND "+key+"=? FOR UPDATE",a.context().tenant_id(),id));for(String field:List.of("tenant_id","project_id","schema_version","schema_manifest_sha256","created_by","created_at","classification"))if(!Objects.equals(original.get(field),ar.get(field)))bad();if(!"1.0.0".equals(str(original,"schema_version"))||!manifest().equals(str(original,"schema_manifest_sha256"))||ar.get("reason_code")!=null||!"1".equals(str(ev,"aggregate_revision"))||!Objects.equals(original.get("created_at"),ev.get("occurred_at"))||!a.context().tenant_id().equals(str(ev,"tenant_id")))bad();if(!project.equals(str(ar,"project_id"))||!actor.equals(str(ar,"subject_id"))||!action.equals(str(ar,"action"))||!"SUCCESS".equals(str(ar,"result"))||!id.equals(str(ar,"request_id"))||!id.equals(str(ar,"trace_id"))||!receipt.equals(codec.read(str(ar,"resource_ref")))||!receipt.equals(codec.read(str(ev,"payload")))||!action.equals(str(ev,"event_type"))||!id.equals(str(ev,"aggregate_id")))bad();}
    private Map<String,Object> metadata(EnterpriseAccess.Admission a,LocalDateTime at,boolean schema)throws Exception{var m=new LinkedHashMap<String,Object>();m.put("tenant_id",a.context().tenant_id());m.put("schema_version","1.0.0");m.put("created_by",a.actorId());m.put("created_at",at);m.put("classification",identity.classification());if(schema)m.put("schema_manifest_sha256",manifest());return m;}
    private void version(String tenant,String project,String id,String kind,String hash){changed(db.update("INSERT INTO version_registry(tenant_id,owner_project_id,version_id,entity_kind,content_sha256) VALUES(?,?,?,?,?)",tenant,project,id,kind,hash));}
    private void insert(String table,Map<String,Object> row){String columns=String.join(",",row.keySet());changed(db.update("INSERT INTO "+table+"("+columns+") VALUES("+String.join(",",Collections.nCopies(row.size(),"?"))+")",row.values().toArray()));}
    private LocalDateTime now(){return Objects.requireNonNull(db.queryForObject("SELECT UTC_TIMESTAMP(6)",LocalDateTime.class));}private static String id(){return UUID.randomUUID().toString();}private static String str(Map<String,Object> r,String k){return Objects.requireNonNull(r.get(k)).toString();}private static <T>T one(List<T> r){if(r.size()!=1)bad();return r.get(0);}private static void changed(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private static void limit(){throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);}
}
